#!/usr/bin/env node
// Generate docs/widgets/*.md from the README of every widget folder.
//
//   node tools/gen-docs.mjs             write docs/widgets/index.md and docs/widgets/<type>.md
//   node tools/gen-docs.mjs --check     write nothing; exit 1 when a generated file is missing or out of date
//
// Source: src/widgets/<type>/README.md, a Markdown file that starts with a front matter block
//
//   ---
//   type: cover          the widget type (must equal the folder name)
//   label: Blinds        the name shown in the card picker
//   entity: required     required | none | custom
//   since: 4.0           first version that had the widget
//   ---
//
// The widget READMEs are the only place the option tables are written by hand. This tool copies each body
// into docs/widgets/ unchanged, adds one line of facts under the title, and builds the index from the front
// matter, so the public docs cannot drift from the widget folders. Overviews (src/overviews/<type>/README.md,
// same front matter plus an optional `domains: [weather]`) are generated the same way into
// docs/overviews/<type>.md and docs/overviews/index.md.
import fs from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';

const REPO = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const WIDGETS_DIR = 'src/widgets';
const OVERVIEWS_DIR = 'src/overviews';
const OUT_DIR = 'docs/widgets';
const OVERVIEWS_OUT_DIR = 'docs/overviews';
const NOTICE = 'Generated by tools/gen-docs.mjs from';

const ENTITY_TEXT = {
  required: 'required',
  none: 'none',
  custom: 'scene, script, button or input_button'
};

/** Split `---\nkey: value\n---\nbody` into `{meta, body}`. Throws when the block is missing. */
export function parseReadme(text, source) {
  const match = /^---\r?\n([\s\S]*?)\r?\n---\r?\n([\s\S]*)$/.exec(text);
  if (!match)
    throw new Error(`${source}: README needs a front matter block (type, label, entity, since)`);
  const meta = {};
  for (const line of match[1].split(/\r?\n/)) {
    const pair = /^([A-Za-z_]+):\s*(.*)$/.exec(line.trim());
    if (pair) meta[pair[1]] = pair[2].trim();
  }
  for (const key of ['type', 'label', 'entity', 'since']) {
    if (!meta[key]) throw new Error(`${source}: front matter is missing "${key}"`);
  }
  return {meta, body: match[2].replace(/^\s+/, '')};
}

/** Module folders (widgets or overviews) that have an index.js, sorted like the generated index. */
function widgetFolders(root, base = WIDGETS_DIR) {
  const dir = path.join(root, base);
  if (!fs.existsSync(dir)) return [];
  return fs
    .readdirSync(dir, {withFileTypes: true})
    .filter((e) => e.isDirectory() && !e.name.startsWith('_'))
    .map((e) => e.name)
    .filter((name) => fs.existsSync(path.join(dir, name, 'index.js')))
    .sort();
}

/** Preferred display order of the built-in kinds; unknown kinds follow alphabetically. */
function byOrder(root) {
  const order = {};
  for (const name of widgetFolders(root)) {
    const source = fs.readFileSync(path.join(root, WIDGETS_DIR, name, 'index.js'), 'utf8');
    order[name] = Number(/\border:\s*(\d+)/.exec(source)?.[1] ?? 9999);
  }
  return (a, b) => order[a] - order[b] || a.localeCompare(b);
}

/** Overview kinds in `order`, then by name. */
function overviewOrder(root) {
  const order = {};
  for (const name of widgetFolders(root, OVERVIEWS_DIR)) {
    const source = fs.readFileSync(path.join(root, OVERVIEWS_DIR, name, 'index.js'), 'utf8');
    order[name] = Number(/\border:\s*(\d+)/.exec(source)?.[1] ?? 9999);
  }
  return (a, b) => order[a] - order[b] || a.localeCompare(b);
}

const domainsOf = (meta) =>
  (/^\[(.*)\]$/.exec(meta.domains ?? '')?.[1] ?? '')
    .split(',')
    .map((d) => d.trim())
    .filter(Boolean);

const overviewEntity = (meta) => {
  const domains = domainsOf(meta);
  const kind = domains.length ? `, a ${domains.map((d) => `\`${d}\``).join(' or ')} entity` : '';
  return `${ENTITY_TEXT[meta.entity] ?? meta.entity}${kind}`;
};

function overviewPageFor({meta, body}) {
  const [title, ...rest] = body.split('\n');
  const facts =
    `> Overview type \`${meta.type}\` (since ${meta.since}). Entity: ${overviewEntity(meta)}. Card type ` +
    `\`custom:houseview-${meta.type.replaceAll('_', '-')}-overview-card\` (widget type \`${meta.type}_overview\`), screensaver \`type: ${meta.type}\`.`;
  return [
    `<!-- ${NOTICE} src/overviews/${meta.type}/README.md. Do not edit this file. -->`,
    '',
    title,
    '',
    facts,
    ...rest,
    ''
  ]
    .join('\n')
    .replace(/\n{3,}/g, '\n\n');
}

function overviewIndexFor(entries) {
  const rows = entries.map(
    ({meta}) =>
      `| [${meta.label}](${meta.type}.md) | \`${meta.type}\` | \`custom:houseview-${meta.type.replaceAll('_', '-')}-overview-card\` | ` +
      `${overviewEntity(meta)} | ${meta.since} |`
  );
  return [
    `<!-- ${NOTICE} the front matter of each src/overviews/<type>/README.md. Do not edit this file. -->`,
    '',
    '# Overviews',
    '',
    'An overview fills a whole page. Use it as a [screensaver](../screensavers.md) over a HouseView carousel, ' +
      'as a page card in the `cards` list, or as a standalone card with the card type in the third column.',
    '',
    '| Overview | Type | Card type | Entity | Since |',
    '| --- | --- | --- | --- | --- |',
    ...rows,
    ''
  ].join('\n');
}

function pageFor({meta, body}) {
  const tag = `custom:houseview-${meta.type}-card`;
  const [title, ...rest] = body.split('\n');
  const facts =
    `Card type \`${tag}\`, or \`type: ${meta.type}\` in the \`cards\` list of \`custom:houseview-card\`. ` +
    `Available since ${meta.since}.`;
  return [
    `<!-- ${NOTICE} src/widgets/${meta.type}/README.md. Do not edit this file. -->`,
    '',
    title,
    '',
    facts,
    ...rest,
    ''
  ]
    .join('\n')
    .replace(/\n{3,}/g, '\n\n');
}

function indexFor(entries) {
  const rows = entries.map(
    ({meta}) =>
      `| [${meta.label}](${meta.type}.md) | \`${meta.type}\` | \`custom:houseview-${meta.type}-card\` | ` +
      `${ENTITY_TEXT[meta.entity] ?? meta.entity} | ${meta.since} |`
  );
  return [
    `<!-- ${NOTICE} the front matter of each src/widgets/<type>/README.md. Do not edit this file. -->`,
    '',
    '# Widgets',
    '',
    'Every widget works in two ways. Put it in the `cards` list of a [`custom:houseview-card`](../configuration.md) carousel with ' +
      '`type: <widget type>`, or add it to any dashboard as a card of its own with the card type in the third column. ' +
      'All widgets accept `size` (`normal`, `wide`, `tall`, `large`) and, unless the page says otherwise, `name`. ' +
      'Single-button widgets also accept the [action options](../actions.md) `tap_action`, `hold_action` and `double_tap_action`.',
    '',
    '| Widget | Widget type | Card type | Entity | Since |',
    '| --- | --- | --- | --- | --- |',
    ...rows,
    '',
    'Besides the widgets above, [overview cards](../screensavers.md) paint a whole page, for example the ' +
      '[weather overview](../overviews/weather.md).',
    ''
  ].join('\n');
}

/**
 * Build every generated file.
 * @returns {{files: Map<string,string>, warnings: string[]}} path (relative to the repo) to content
 */
export function generate(root = REPO) {
  const files = new Map();
  const warnings = [];
  const entries = [];
  for (const name of widgetFolders(root).sort(byOrder(root))) {
    const readme = path.join(root, WIDGETS_DIR, name, 'README.md');
    if (!fs.existsSync(readme)) {
      warnings.push(
        `src/widgets/${name}/README.md is missing, so docs/widgets/${name}.md is not generated`
      );
      continue;
    }
    const parsed = parseReadme(fs.readFileSync(readme, 'utf8'), `src/widgets/${name}/README.md`);
    if (parsed.meta.type !== name) {
      throw new Error(
        `src/widgets/${name}/README.md: front matter type "${parsed.meta.type}" is not the folder name`
      );
    }
    entries.push(parsed);
    files.set(`${OUT_DIR}/${name}.md`, pageFor(parsed));
  }
  files.set(`${OUT_DIR}/index.md`, indexFor(entries));

  const overviews = [];
  for (const name of widgetFolders(root, OVERVIEWS_DIR).sort(overviewOrder(root))) {
    const readme = path.join(root, OVERVIEWS_DIR, name, 'README.md');
    if (!fs.existsSync(readme)) {
      warnings.push(
        `src/overviews/${name}/README.md is missing, so docs/overviews/${name}.md is not generated`
      );
      continue;
    }
    const parsed = parseReadme(fs.readFileSync(readme, 'utf8'), `src/overviews/${name}/README.md`);
    if (parsed.meta.type !== name) {
      throw new Error(
        `src/overviews/${name}/README.md: front matter type "${parsed.meta.type}" is not the folder name`
      );
    }
    overviews.push(parsed);
    files.set(`${OVERVIEWS_OUT_DIR}/${name}.md`, overviewPageFor(parsed));
  }
  if (overviews.length) files.set(`${OVERVIEWS_OUT_DIR}/index.md`, overviewIndexFor(overviews));
  return {files, warnings};
}

function main() {
  const check = process.argv.includes('--check');
  const {files, warnings} = generate();
  for (const warning of warnings) console.warn(`warning: ${warning}`);
  let stale = 0;
  for (const [file, content] of files) {
    const target = path.join(REPO, file);
    const current = fs.existsSync(target) ? fs.readFileSync(target, 'utf8') : null;
    if (current === content) continue;
    stale++;
    if (check) {
      console.error(`out of date: ${file}`);
    } else {
      fs.mkdirSync(path.dirname(target), {recursive: true});
      fs.writeFileSync(target, content);
      console.log(`wrote ${file}`);
    }
  }
  if (check && (stale || warnings.length)) {
    console.error('Run: node tools/gen-docs.mjs');
    process.exit(1);
  }
  if (!stale) console.log(`docs/widgets and docs/overviews are up to date (${files.size} files)`);
}

if (import.meta.url === `file://${process.argv[1]}`) main();
